     "type": "string"
    },
    "reason": {
     "type": "string"
    }
   }
  },
  "corrections": {
   "type": "array",
   "items": {
    "type": "object",
    "additionalProperties": false,
    "required": [
     "document",
     "paragraph",
     "original_text",
     "corrected_text"
    ],
    "properties": {
