      "type": "string"
     },
     "paragraph": {
      "type": "string"
     }
    }
   }
  },
  "amoc_paragraph": {
   "type": "string"
  },
  "ambiguities": {
   "type": "array",
   "items": {
    "type": "object",
    "additionalProperties": false,
    "required": [
