      "type": "string"
     },
     "description": {
      "type": "string"
     },
     "readings": {
      "type": "array",
      "items": {
       "type": "string"
      }
     }
    }
   }
  },
  "notes": {
   "type": "array",
   "items": {
    "type": "string"
   }
  }
 }
